 "content": "from collections import deque


def transform(grid):
    """Draw edge-to-edge 1-rays, recoloring every touched 2-object as well."""
    h, w = len(grid), len(grid[0])
    rows = {r for r in range(h) if grid[r][0] == 1 and grid[r][w - 1] == 1}
    cols = {c for c in range(w) if grid[0][c] == 1 and grid[h - 1][c] == 1}
    out = [row[:] for row in grid]

    # Mark 2-components hit by one of the full-length rays.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            hit = False
            while q:
                rr, cc = q.popleft()
                component.append((rr, cc))
                if rr in rows or cc in cols:
                    hit = True
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            if hit:
                for rr, cc in component:
                    out[rr][cc] = 1

    for r in rows:
        out[r] = [1] * w
    for c in cols:
        for r in range(h):
            out[r][c] = 1
    return out
